<?php################################## Global Update 2026 #####
#### WindLand RPG v2.0 ###################################### Функции которые как-то связанны с боевой системойfunction end_battle($pers){	GLOBAL $GOOD_DAY,$options,$db;	// В $pers["f_turn"] хранится переменная победа. =1 - победили. =0 - проиграли.	$fight = $db->sqla("SELECT * FROM `fights` WHERE `id`='".$pers["cfight"]."'", __FILE__,__LINE__,__FUNCTION__,__CLASS__);	if ($fight["turn"]=="finish" and $fight["type"]=='f')	{		if(($pers["lb_attack"]-40)<tme()) $pers["lb_attack"] = tme()-40;		$curstate = 0;		$win = ($pers["f_turn"]==1)?"Победа!":"Поражение.";				######Праздник		if($fight["special"]==1)		{		//	include("holyday/new_year.php");		}				######Турниры		if($pers["tour"]==1)		{			$t1 = $db->sqla("SELECT * FROM quest WHERE id = 2", __FILE__,__LINE__,__FUNCTION__,__CLASS__);			if($pers["f_turn"]!=1)			{				set_vars("tour=0",$pers["uid"]);				say_to_chat('s',"Вы проиграли турнир...",1,$pers["user"],'*',0);			}			elseif($t1["type"]==2)			{				say_to_chat('s',"Вы прошли во вторую стадию турнира!",1,$pers["user"],'*',0);				$db->sql("UPDATE `users` SET chp=hp,cma=ma WHERE `uid`='".$pers["uid"]."' ", __FILE__,__LINE__,__FUNCTION__,__CLASS__);				$db->sql("UPDATE p_auras SET esttime=0 WHERE uid=".$pers["uid"]." and special>=3 and special<=5 and esttime>".tme(), __FILE__,__LINE__,__FUNCTION__,__CLASS__);				$pers["chp"]=$pers["hp"];				$pers["cma"]=$pers["ma"];			}			elseif($t1["type"]==3)			{				set_vars("tour=0,coins=coins+10,exp=exp+10000,money=money+500",$pers["uid"]);				say_to_chat('s',"Вы выиграли турнир!",1,$pers["user"],'*',0);				$db->sql("UPDATE quest SET finished=1,time=".tme()." WHERE id = 2", __FILE__,__LINE__,__FUNCTION__,__CLASS__);			}		}		if($pers["tour"]==2)		{			$t1 = $db->sqla("SELECT * FROM quest WHERE id = 3", __FILE__,__LINE__,__FUNCTION__,__CLASS__);			if($pers["f_turn"]==0)			{				set_vars("tour=0",$pers["uid"]);				say_to_chat('s',"Вы проиграли турнир...",1,$pers["user"],'*',0);			}			elseif($t1["type"]==2)			{				say_to_chat('s',"Вы прошли во вторую стадию турнира!",1,$pers["user"],'*',0);				$db->sql("UPDATE `users` SET chp=hp,cma=ma WHERE `uid`='".$pers["uid"]."' ", __FILE__,__LINE__,__FUNCTION__,__CLASS__);				$db->sql("UPDATE p_auras SET esttime=0 WHERE uid=".$pers["uid"]." and special>=3 and special<=5 and esttime>".tme(), __FILE__,__LINE__,__FUNCTION__,__CLASS__);				$pers["chp"]=$pers["hp"];				$pers["cma"]=$pers["ma"];			}			elseif($t1["type"]==3)			{				set_vars("tour=0,coins=coins+20,exp=exp+100000,money=money+1000",$pers["uid"]);				say_to_chat('s',"Вы выиграли турнир!",1,$pers["user"],'*',0);				$db->sql("UPDATE quest SET finished=1,time=".tme()." WHERE id = 3", __FILE__,__LINE__,__FUNCTION__,__CLASS__);			}		}		if($pers["tour"]==3)		{			$t1 = $db->sqla("SELECT * FROM quest WHERE id = 4", __FILE__,__LINE__,__FUNCTION__,__CLASS__);			if($pers["f_turn"]==0)			{				set_vars("tour=0",$pers["uid"]);				say_to_chat('s',"Вы проиграли турнир...",1,$pers["user"],'*',0);			}			elseif($t1["type"]==2)			{				say_to_chat('s',"Вы прошли во вторую стадию турнира!",1,$pers["user"],'*',0);				$db->sql("UPDATE `users` SET chp=hp,cma=ma WHERE `uid`='".$pers["uid"]."' ", __FILE__,__LINE__,__FUNCTION__,__CLASS__);				$db->sql("UPDATE p_auras SET esttime=0 WHERE uid=".$pers["uid"]." and special>=3 and special<=5 and esttime>".tme(), __FILE__,__LINE__,__FUNCTION__,__CLASS__);				$pers["chp"]=$pers["hp"];				$pers["cma"]=$pers["ma"];			}			elseif($t1["type"]==3)			{				set_vars("tour=0,coins=coins+30,exp=exp+200000,money=money+2000",$pers["uid"]);				say_to_chat('s',"Вы выиграли турнир!",1,$pers["user"],'*',0);				$db->sql("UPDATE quest SET finished=1,time=".tme()." WHERE id = 4", __FILE__,__LINE__,__FUNCTION__,__CLASS__);			}		}				$chat_c = '';		if ($pers["sign"] !='none' and $pers["sign"] !='')		{			$proca = 0.01;			$cexp = $pers["exp_chat"]*$proca;			if ( $cexp > '' )			{				$chat_c .= 'Ваш клан получил <b>'.ceil($cexp).'</b> опыта.';				$db->sql("UPDATE `clans` SET `exp`=`exp`+'".ceil($cexp)."' WHERE `sign`='".$pers["sign"]."' LIMIT 1", __FILE__,__LINE__,__FUNCTION__,__CLASS__);			}		}		####### Турниры кончились		say_to_chat('s',"<b>Поединок завершен. ".$win."</b> Нанесено урона: <b>".$pers["fexp"]."</b> , получено <font class=hp>боевого опыта: <b>".$pers["exp_chat"]."</b></font>. Убийства людей: <b>".$pers["kills"]."</b> ".$chat_c." <a href=\"/fight.php?id=".$pers["cfight"]."\" target=_blank class=timef>Лог боя</a>.",1,$pers["user"],'*',0);				if ( $pers["kills"]>0 )		{			$pers["coins"]+=$pers["kills"];			say_to_chat('s',"<i><b>+".$pers["kills"]." пергамент.</b></i>",1,$pers["user"],'*',0);		}		if ($pers["gain_time"]>(tme()-1200))		{			 $curstate = 2;			 if ($pers["f_turn"]!=1) set_vars("gain_time=0",$pers["uid"]);		}		if ($pers["f_turn"]!=1) set_vars("tour=0",$pers["uid"]);		$db->sql("UPDATE `users` SET `curstate`=".$curstate." ,`cfight`=0 , `chp`=`chp`+2 , `od_b`=0 ,`fexp`=0 ,`exp_in_f`=0,f_turn=0,exp_chat=0,apps_id=0,kills=0,coins=coins+".$pers["kills"].",lb_attack=".$pers["lb_attack"]." WHERE `uid`='".$pers["uid"]."' ", __FILE__,__LINE__,__FUNCTION__,__CLASS__);		$pers["cfight"]=0;		$pers["curstate"] = $curstate;		$pers["chp"]+=2;		$pers["fexp"]=0;		$pers["exp_in_f"]=0;		$pers["f_turn"]=0;		$pers["od_b"]=0;		$pers["kills"]=0;		if ($options[7]<>"no") echo "<script>top.flog_unset();</script>";		echo "<script>top.flog_clear();</script>";		$db->sql("UPDATE `u_blasts` SET cur_turn_colldown=0 WHERE uidp=".$pers["uid"], __FILE__,__LINE__,__FUNCTION__,__CLASS__);		$db->sql("UPDATE `u_auras` SET cur_turn_colldown=0 WHERE uidp=".$pers["uid"], __FILE__,__LINE__,__FUNCTION__,__CLASS__);		$db->sql("UPDATE `p_auras` SET turn_esttime=0 WHERE uid=".$pers["uid"], __FILE__,__LINE__,__FUNCTION__,__CLASS__);		$tmp = $db->sqlr("SELECT esttime FROM p_auras WHERE uid=".$pers["uid"]." and special=16 and esttime>".tme(),0, __FILE__,__LINE__,__FUNCTION__,__CLASS__);		$_REGEN = mtrunc($tmp - tme());		if($_REGEN || ($GOOD_DAY&GD_HUMANHEAL))		{			//sql("UPDATE `users` SET chp=hp,cma=ma WHERE `uid`='".$pers["uid"]."' ");			$db->sql("UPDATE p_auras SET esttime=0 WHERE uid=".$pers["uid"]." and special>=3 and special<=5 and esttime>".tme(), __FILE__,__LINE__,__FUNCTION__,__CLASS__);			/*$pers["chp"]=$pers["hp"];			$pers["cma"]=$pers["ma"];*/		}	}	return $pers;}function begin_fight($names,$namesvs,$type,$travm,$timeout,$oruj,$loc,$battle_type = 0,$closed = 0,$special = 0){	GLOBAL $player,$db;	$closed = intval($closed);	$bots_in = 0;	$loc = intval($loc);	#Отключаем тактические бои.	if ($player->pers["location"]=='inst_prefight') $loc = 1; else $loc = 0;	if ($loc==0)	{		$maxx=1;		$maxy=1;	}	elseif ($loc<6)	{		$maxx = 15;		$maxy = 5;	}	if ($loc) $bplace = $db->sqla("SELECT * FROM battle_places WHERE id=".$loc, __FILE__,__LINE__,__FUNCTION__,__CLASS__);	$idf = 0;	$help_param = 0;	while( ($idf<11) and ($help_param<100) )	{		$help_param++;		$db->sql("INSERT INTO `fights` (`oruj`,`travm`,`timeout`,`ltime`,`bplace`,`maxx`,`maxy`,`stones`,`closed`,`special`)			VALUES ('".$oruj."','".$travm."',".$timeout." ,".tme().",".$loc.",".$maxx.",".$maxy.",".intval($battle_type).",".$closed.",".intval($special).")", __FILE__,__LINE__,__FUNCTION__,__CLASS__);		$idf = $db->insert_id();	}	$bot_id_max = $idf*100;	if ($names[strlen($names)-1]=='|') $names = substr($names,0,strlen($names)-1);	if ($namesvs[strlen($namesvs)-1]=='|') $namesvs = substr($namesvs,0,strlen($namesvs)-1);	$all = 'Бой между ';	unset ($turns);	$turns[0] = '';	unset ($exps);	$exps[0] = 0;	$n = -1;$i=0;	$PLAYERS = 0;	$tmp1 = explode("|",$names);	$T1_count = count($tmp1);	$xf=4-intval($T1_count/$maxy);	$yf=floor($maxy/2)-1;	$persons = array();	foreach ($tmp1 as $tmp) 	{		if($loc>0)		while ( substr_count($bplace["xy"],"|".$xf."_".$yf."|") and $xf>0 )		{			$yf++;			if ($yf%$maxy==0)			{				$yf=0;				$xf--;			}		}		$PLAYERS++;		$bplace["xy"] .= "|".$xf."_".$yf."|";		if (strpos(" ".$tmp,"bot=")>0)		{			$e = explode("=",$tmp);			$p = $db->sqla("SELECT * FROM `bots` WHERE `id`='".$e[1]."'", __FILE__,__LINE__,__FUNCTION__,__CLASS__);			if (@$p["id"])			{				$p["rank_i"] = ($p["s1"]+$p["s2"]+$p["s3"]+$p["s4"]+$p["s5"]+$p["s6"]+$p["kb"])*0.3 + ($p["mf1"]+$p["mf2"]+$p["mf3"]+$p["mf4"])*0.03 + ($p["hp"]+$p["ma"])*0.04+($p["udmin"]+$p["udmax"])*0.3;				$bot_id_max++;				$db->sql("INSERT INTO `bots_battle` ( `user` , `level` , `sign` , `s1` , `s2` , `s3` , `s4` , `s5` , `s6` , `kb` , `mf1` , `mf2` , `mf3` , `mf4` , `mf5` , `udmin` , `udmax` , `hp` , `ma` , `chp` , `cma` , `id` , `pol` , `obr` , `wears` , `rank_i` , `cfight` , `fteam` , `xf` , `yf` , `bid`, `id_skin` , `droptype`,`dropvalue`,`dropfrequency`,`magic_resistance`,`special`)					VALUES ('".$p["user"]."', '".$p["level"]."', 'none', '".$p["s1"]."', '".$p["s2"]."', '".$p["s3"]."', '".$p["s4"]."', '".$p["s5"]."', '".$p["s6"]."', '".$p["kb"]."', '".$p["mf1"]."', '".$p["mf2"]."', '".$p["mf3"]."', '".$p["mf4"]."', '".$p["mf5"]."', '".$p["udmin"]."', '".$p["udmax"]."', '".$p["hp"]."', '".$p["ma"]."', '".$p["hp"]."', '".$p["ma"]."', '".(-1*$bot_id_max)."' , 'male', '".$p["obr"]."', '', '".$p["rank_i"]."', '".$idf."', '1', '".$xf."', '".$yf."', '".$p["id"]."',".$p["id_skin"].",".intval($p["droptype"]).",".intval($p["dropvalue"]).",".intval($p["dropfrequency"]).",".intval($p["magic_resistance"]).",".intval($p["special"]).");", __FILE__,__LINE__,__FUNCTION__,__CLASS__);				$bots_in = 1;			}			else array_splice($tmp,$i,1);		}		else		{			$p = $db->sqla("SELECT user,level,sign,rank_i,chp,hp,cma,ma,sm6,sm7,lastom,uid,invisible,tire FROM `users` WHERE `user`='".$tmp."'", __FILE__,__LINE__,__FUNCTION__,__CLASS__);			$db->sql("UPDATE `users` SET `xf`=".$xf.",`yf`=".$yf.",".hp_ma_up($p["chp"],$p["hp"],$p["cma"],$p["ma"],$p["sm6"],$p["sm7"],$p["lastom"],$p["tire"],1).",`cfight`='".$idf."' ,`curstate`=4 , `refr`=1 , damage_get=chp , damage_give=0 , fteam = 1 WHERE `uid`='".$p["uid"]."'", __FILE__,__LINE__,__FUNCTION__,__CLASS__);			$p["lib"] = $p["user"];			if ($p["invisible"]>tme()) {$p["user"]='невидимка';$p["sign"]='none';$p["level"]='??';}			$persons[] = $p["uid"];		}				$all .= "<img src=images/signs/".$p['sign'].".gif><font class=bnick color=#087C20>".$p["user"]."</font>[<font class=lvl>".$p["level"]."</font>] ,";		$i++;	}	if($PLAYERS==0) return false;	$all = substr ($all,0,strlen ($all)-1);	$all .= 'и ';	$tmp2 = explode("|",$namesvs);	$i=0;	$T2_count = count($tmp2);	$xf=$maxx-(4-intval($T2_count/$maxy));	$yf=floor($maxy/2)-1;		foreach ($tmp2 as $tmp) 	{		if($loc>0)		while (substr_count($bplace["xy"],"|".$xf."_".$yf."|") and $xf<$maxx)		{			$yf++;			if ($yf%$maxy==0)			{				$yf=0;				$xf++;			}		}		$PLAYERS++;		$bplace["xy"] .= "|".$xf."_".$yf."|";		if (strpos(" ".$tmp,"bot=")>0)		{			$e = explode("=",$tmp);			$p = $db->sqla("SELECT * FROM `bots` WHERE `id`='".$e[1]."'", __FILE__,__LINE__,__FUNCTION__,__CLASS__);			if (@$p["id"])			{				$p["rank_i"] = ($p["s1"]+$p["s2"]+$p["s3"]+$p["s4"]+$p["s5"]+$p["s6"]+$p["kb"])*0.3 + ($p["mf1"]+$p["mf2"]+$p["mf3"]+$p["mf4"])*0.03 + ($p["hp"]+$p["ma"])*0.04+($p["udmin"]+$p["udmax"])*0.3;				$bot_id_max++;				$db->sql("INSERT INTO `bots_battle` ( `user` , `level` , `sign` , `s1` , `s2` , `s3` , `s4` , `s5` , `s6` , `kb` , `mf1` , `mf2` , `mf3` , `mf4` , `mf5` , `udmin` , `udmax` , `hp` , `ma` , `chp` , `cma` , `id` , `pol` , `obr` , `wears` , `rank_i` , `cfight` , `fteam` , `xf` , `yf` , `bid`, `id_skin` , `droptype`,`dropvalue`,`dropfrequency`,`magic_resistance`,`special`)					VALUES ('".$p["user"]."', '".$p["level"]."', 'none', '".$p["s1"]."', '".$p["s2"]."', '".$p["s3"]."', '".$p["s4"]."', '".$p["s5"]."', '".$p["s6"]."', '".$p["kb"]."', '".$p["mf1"]."', '".$p["mf2"]."', '".$p["mf3"]."', '".$p["mf4"]."', '".$p["mf5"]."', '".$p["udmin"]."', '".$p["udmax"]."', '".$p["hp"]."', '".$p["ma"]."', '".$p["hp"]."', '".$p["ma"]."', '".(-1*$bot_id_max)."' , 'male', '".$p["obr"]."', '', '".$p["rank_i"]."', '".$idf."', '2', '".$xf."', '".$yf."', '".$p["id"]."',".$p["id_skin"].",".intval($p["droptype"]).",".intval($p["dropvalue"]).",".intval($p["dropfrequency"]).",".intval($p["magic_resistance"]).",".intval($p["special"]).");", __FILE__,__LINE__,__FUNCTION__,__CLASS__);				$bots_in = 1;			}			else			array_splice($tmp2,$i,1);		}		else		{			$p = $db->sqla("SELECT user,level,sign,rank_i,chp,hp,cma,ma,sm6,sm7,lastom,uid,invisible,tire FROM `users` WHERE `user`='".$tmp."'", __FILE__,__LINE__,__FUNCTION__,__CLASS__);			$db->sql("UPDATE `users` SET `xf`=".$xf.",`yf`=".$yf.",".hp_ma_up($p["chp"],$p["hp"],$p["cma"],$p["ma"],$p["sm6"],$p["sm7"],$p["lastom"],$p["tire"],1).",`cfight`='".$idf."' ,`curstate`=4 , `refr`=1 , damage_get=chp , damage_give=0 , fteam = 2 WHERE `uid`='".$p["uid"]."'", __FILE__,__LINE__,__FUNCTION__,__CLASS__);			$p["lib"] = $p["user"];			if ($p["invisible"]>tme()) {$p["user"]='невидимка';$p["sign"]='none';$p["level"]='??';}			$persons[] = $p["uid"];		}		$all .= "<img src=images/signs/".$p['sign'].".gif><font class=bnick color=#0052A6>".$p["user"]."</font>[<font class=lvl>".$p["level"]."</font>] ,";		$i++;	}		if($i==0) return false;	$bots_in = ($bots_in)?0:1;	$all = addslashes(substr($all,0,strlen($all)-1).".(".$type.")");	$db->sql("UPDATE fights SET players=".$PLAYERS." , nobots=".intval($bots_in).", closed=".$closed." WHERE id=".$idf."", __FILE__,__LINE__,__FUNCTION__,__CLASS__);	add_flog($all,$idf);		$names = $tmp1;	$namesvs = $tmp2;	$query1 = '';	$query2 = '';	foreach ($names as $n) $query1 .= "`user`='".$n."' or";	foreach ($namesvs as $n) $query2 .= "`user`='".$n."' or";	$query1 = substr ($query1,0,strlen ($query1)-2);	$query2 = substr ($query2,0,strlen ($query2)-2);	foreach($persons as $p)	{		$db->sql("INSERT INTO `battle_logs` (`uid` ,`time` ,`cfight` ,`text` ) VALUES ('".$p."', '".tme()."', '".$idf."', '".$all."');", __FILE__,__LINE__,__FUNCTION__,__CLASS__);	}	return $idf;}function add_flog($txt,$cfight){	GLOBAL $battle_log,$db;	if (empty($cfight))	{		$cfight = $GLOBALS['player']->pers["cfight"];	}	if ($txt[strlen($txt)-1]=='%') $txt = substr($txt,0,strlen($txt)-1);	$db->sql("INSERT INTO `fight_log` ( `time` , `log` , `cfight` , `turn` )		VALUES ('".date("H:i")."', '".addslashes($txt)."', '".$cfight."', '".round((tme()+microtime()),2)."');", __FILE__,__LINE__,__FUNCTION__,__CLASS__);	$txt = "<font class=timef>".date("H:i")."</font> ".$txt;	$txt = str_replace("%","<br><font class=timef>".date("H:i")."</font> ",$txt);	$battle_log .= $txt;	$db->sql("UPDATE `fights` SET `all`=CONCAT('".addslashes($txt).";',`all`) , `ltime`='".tme()."' WHERE `id`='".$cfight."' ;", __FILE__,__LINE__,__FUNCTION__,__CLASS__);}function show_pers_in_f($_pers,$inv){	$s = '<table border=0 cellspacing=0 cellpadding=0><tr><td valign=top width=221 colspan=3><script>';	GLOBAL $sh,$oj,$or1,$or2,$sa,$na,$po,$pe,$br,$kam1,$kam2,$kam3,$kam4,$z1,$z2,$z3,$ko1,$ko2,$player,$lo,$db;	if ( $_pers['uid']<> UID )	{		$perst = $player->pers;		$player->pers = $_pers;		include(ROOT.'/inc/inc/p_clothes.php');		$player->pers = $perst;		unset($perst);	}	if ($_pers["invisible"]>tme() and $_pers["uid"]<>$_COOKIE["uid"])	{		$wears = array();		for ($i=0;$i<18;$i++)		{			$m = array();			$m["image"]='slots/pob'.($i+1);			$m["id"]="0";			$wears[$i]=$m;		}				$sh = $wears[0];		$na = $wears[8];		$oj = $wears[1];		$pe = $wears[9];		$or1 = $wears[2];		$or2 = $wears[10];		$po = $wears[3];		$z1 = $wears[4];		$z2 = $wears[5];		$z3 = $wears[6];		$sa = $wears[7];		$ko1 = $wears[11];		$ko2 = $wears[12];		$br = $wears[13];		$kam1 = $wears[14];		$kam2 = $wears[15];		$kam3 = $wears[16];		$kam4 = $wears[17];		$lo = $wears[18];		$_pers["obr"]='invisible';		$_pers["user"]='<i>невидимка</i>';		$_pers["sign"]='none';		$_pers["level"]='??';		$_pers["aura"]='';		$_pers["s1"]='??';		$_pers["s2"]='??';		$_pers["s3"]='??';		$_pers["s4"]='??';		$_pers["s5"]='??';		$_pers["s6"]='??';		$_pers["kb"]='??';		$_pers["mf1"]='??';		$_pers["mf2"]='??';		$_pers["mf3"]='??';		$_pers["mf4"]='??';		$_pers["mf5"]='??';		$_pers["hp"]='1';		$_pers["chp"]='1';		$_pers["ma"]='1';		$_pers["cma"]='1';	}	$s .= "InFight=1;";	$s .= "show_pers_new('".$sh["image"]."','".$sh["id"]."','".$oj["image"]."','".$oj["id"]."','".$or1["image"]."','".$or1["id"]."','".$po["image"]."','".$po["id"]."','".$z1["image"]."','".$z1["id"]."','".$z2["image"]."','".$z2["id"]."','".$z3["image"]."','".$z3["id"]."','".$sa["image"]."','".$sa["id"]."','".$na["image"]."','".$na["id"]."','".$pe["image"]."','".$pe["id"]."','".$or2["image"]."','".$or2["id"]."','".$ko1["image"]."','".$ko1["id"]."','".$ko2["image"]."','".$ko2["id"]."','".$br["image"]."','".$br["id"]."','".$_pers["pol"]."_".$_pers["obr"]."',".$inv.",'".$_pers["sign"]."','".$_pers["user"]."','".$_pers["level"]."','".$_pers["chp"]."','".$_pers["hp"]."','".$_pers["cma"]."','".$_pers["ma"]."',".intval($_pers["tire"]).",'".$kam1["image"]."','".$kam2["image"]."','".$kam3["image"]."','".$kam4["image"]."','".$kam1["id"]."','".$kam2["id"]."','".$kam3["id"]."','".$kam4["id"]."','".$lo["id"]."','".$lo["image"]."','".$lo["id"]."','".$lo["image"]."');";	$s .= '</script></td></tr><tr><td>';	if ($_pers["invisible"]<tme() or $pers["uid"]==$_pers["uid"])	{		if ($_pers["uid"]) //$s .= "<div id=prs".$_pers["uid"]." class=aurasc></div>";			$s .= '<br><script>document.write(sbox2b(1,1));</script><div id=prs'.$_pers["uid"].' class=aurasc style="text-align:center;"></div><script>document.write(sbox2e());</script>';		$s.= "<table border=0 cellspacing=0 cellpadding=0 width=100%><tr><td valign=top>";		$r = all_params();		$r[12] = 'rank_i';		for ($i=0;$i<13;$i++)		{			//if ($_pers[$r[$i]]==0) continue;			if($r[$i][0]=='s')			{				$td_class = 'user';				$img = '<img src="images/DS/stats_s'.$r[$i][1].'.png">';			}			else			{				$td_class = 'mf';				$img = '';			}			$s .= '<tr>';			$s .= '<td class='.$td_class.' width=150 nowrap>'.$img.name_of_skill($r[$i]);			$s .= '</td>';			if ($i<6)			{				if ($_pers["uid"]==UID || $pers[$r[$i]]==$_pers[$r[$i]])					$s .= '<td class=user align=right>'.$_pers[$r[$i]].'</td>';				elseif($pers[$r[$i]]>$_pers[$r[$i]])					$s .= '<td class=user align=right><b style="color:#990000">'.$_pers[$r[$i]].'</b></td>';				else					$s .= '<td class=user align=right><b style="color:#009900">'.$_pers[$r[$i]].'</b></td>';			}			elseif($i == 6 or $i==12)			{				if ($_pers["uid"]==UID || $pers[$r[$i]]==$_pers[$r[$i]])					$s .= '<td class=mfb align=right><b>'.$_pers[$r[$i]].'</b></td>';				elseif($pers[$r[$i]]>$_pers[$r[$i]])					$s .= '<td class=mfb align=right><b style="color:#990000">'.$_pers[$r[$i]].'</b></td>';				else					$s .= '<td class=mfb align=right><b style="color:#009900">'.$_pers[$r[$i]].'</b></td>';			}			else			{				if ($_pers["uid"]==UID || $pers[$r[$i]]==$_pers[$r[$i]])					$s .= '<td class=mfb align=right><b>'.$_pers[$r[$i]].'%</b></td>';				elseif($pers[$r[$i]]>$_pers[$r[$i]])					$s .= '<td class=mfb align=right><b style="color:#990000">'.$_pers[$r[$i]].'%</b></td>';				else					$s .= '<td class=mfb align=right><b style="color:#009900">'.$_pers[$r[$i]].'%</b></td>';			}			$s .= '</tr>';		}		$s .= '</table>';		$s .= '</td></tr></table>';		if ($_pers["uid"])		{			$as = $db->sql("SELECT * FROM p_auras WHERE uid=".$_pers["uid"]."", __FILE__,__LINE__,__FUNCTION__,__CLASS__);			$txt = '';			while($a = mysql_fetch_array($as))			{				$txt .= $a["image"].'#<b>'.$a["name"].'</b>@';				$txt .= 'Осталось <i class=timef>'.tp($a["esttime"]-time()).'</i>';				$params = explode("@",$a["params"]);					foreach($params as $par)					{						$p = explode("=",$par);						$perc = '';						if (substr($p[0],0,2)=='mf') $perc = '%';						if ($p[1] and $p[0]<>'cma' and $p[0]<>'chp')						$txt .= '@'.name_of_skill($p[0]).':<b>'.plus_param($p[1]).$perc.'</b>';					}				$txt .= '|';			}			$s .= "<script>view_auras('".$txt."','prs".$_pers["uid"]."');</script>";		}	}	else	{		$s .= '</td></tr></table>';	}	return $s;}// Функция удара от человека.function human_udar ($point,$_pers,$_persvs,$req,$en,$delta){	GLOBAL $colors,$fight,$kl,$die,$db;		if ($_pers["udmin"]<1) $_pers["udmin"]=1;	if ($_pers["udmax"]<1) $_pers["udmax"]=1;	if ($delta<1) $delta=1;	if ($_pers["invisible"]>tme()){$_pers["user"] = '<i>невидимка</i>';$invyou=1;$_pers["pol"]='female';} else $invyou=0;	if ($_persvs["invisible"]>tme()){$_persvs["user"] = '<i>невидимка</i>';$invvs=1;$_persvs["pol"]='female';} else $invvs=0;	if (!$invvs) $nvs = "<font class=bnick color=".$colors[$_persvs["fteam"]].">".$_persvs["user"]."</font>[".$_persvs["level"]."]";	else $nvs = "<font class=bnick color=".$colors[$_persvs["fteam"]]."><i>невидимка</i></font>[??]";	if ( $_pers["pol"]=='female' ) $male='а'; else $male='';	if ( $male=='а' ) $pitalsa = 'пыталась';	else $pitalsa = 'пытался';		if ($_persvs["pol"]=='female')	{		$pogib = 'погибла';		$malevs='а';		$yvvs = 'увернулась';	}	else	{		$pogib = 'погиб';		$malevs='';		$yvvs = 'увернулся';	}	if (!$invyou) $nyou = "<font class=bnick color=".$colors[$_pers["fteam"]].">".$_pers["user"]."</font>[".$_pers["level"]."]";	else $nyou = "<font class=bnick color=".$colors[$_pers["fteam"]]."><i>невидимка</i></font>[??]";	switch ($point)	{		case ("ug"): {$bpoint="bg";$ypoint="удар в голову";break;}		case ("ut"): {$bpoint="bt";$ypoint="удар в грудь";break;}		case ("uj"): {$bpoint="bj";$ypoint="удар по животу";break;}		case ("un"): {$bpoint="bn";$ypoint="удар по ногам";break;}	}	//echo $_persvs[$bpoint]."-",$_persvs["user"]." ".$bpoint."<br>";	$_W = Weared_Weapons($_pers["uid"]);	if($req[$point]!='magic')	$req[$point] -= $_W["OD"];	$_pers["udmin"] +=	$_pers["udmin"]*$_pers["sb2"]/100+					$_W["noji"]["udmin"]*$_pers["sb3"]/200+					$_W["mech"]["udmin"]*$_pers["sb5"]/200+					$_W["topo"]["udmin"]*$_pers["sb6"]/200+					$_W["drob"]["udmin"]*$_pers["sb7"]/200;	$_pers["udmax"] +=	$_pers["udmax"]*$_pers["sb2"]/100+					$_W["noji"]["udmax"]*$_pers["sb3"]/200+					$_W["mech"]["udmax"]*$_pers["sb5"]/200+					$_W["topo"]["udmax"]*$_pers["sb6"]/200+					$_W["drob"]["udmax"]*$_pers["sb7"]/200;	if($_persvs["uid"] and $_persvs["sb4"])		$_persvs["kb"] += $db->sqlr("SELECT SUM(kb) FROM wp WHERE uidp=".intval($_persvs["uid"])." and weared=1 and stype='shit'",0, __FILE__,__LINE__,__FUNCTION__,__CLASS__)*$_persvs["sb4"]/33;	$ud_name = '';	if ($req[$point]==3) $ud_name = 'простой ';	elseif ($req[$point]==5) $ud_name = 'прицельный ';	elseif ($req[$point]==7) $ud_name = 'оглушающий ';	else	{		$spd = $db->sqla("SELECT * FROM `u_special_dmg` WHERE `uid`=".$_pers["uid"]." and `od` = ".intval($req[$point])."", __FILE__,__LINE__,__FUNCTION__,__CLASS__);		$ud_name = "<b>".$spd["name"]."</b> ";	}		if($ud_name=='') return false;	$ud_name .= $ypoint;	$fall = '';	if (!$_persvs["uid"]) $_persvs[$bpoint] = mtrunc(rand(-2,1));	if ( !empty($req[$point])		and ( $req[$point]<>'magic' or($req[$point]=='magic' and !empty($req[$point."p"])) )		and ( $req[$point]<>'kid'or($req[$point]=='kid' and !empty($req[$point."p"])) )		and ( intval($req[$point])>0 or $req[$point]=='kid' or $req[$point]=='magic' )	){		if($_persvs["chp"]>0)		{			$zakname = '';			$kl=1;			$block='';			$blocked=0;			if ($_pers["fstate"]==2)			{				$f_wp = $db->sqla("SELECT * FROM wp WHERE uidp=".$_pers["uid"]." and weared=1 and stype='kid'", __FILE__,__LINE__,__FUNCTION__,__CLASS__);				$_pers["udmin"]=$f_wp["udmin"];				$_pers["udmax"]=$f_wp["udmax"];				$an = $f_wp["arrow_name"];				$ap = $f_wp["arrow_price"]/10;				$ud_name = "[<font class=time>".$an." :: ".$ap." LN</font>]".$ud_name;				$db->sql("UPDATE wp SET arrows=arrows-1 WHERE id='".$f_wp["id"]."'", __FILE__,__LINE__,__FUNCTION__,__CLASS__);				$promax = rand(1,10)-$_pers["mf3"]/100;			}			if (@$spd)			{				if ($spd["type"]==1)				{					 $_pers["udmin"] *= 1+$spd["value"]/100;					 $_pers["udmax"] *= 1+$spd["value"]/100;				}			}						$ydar = ydar($_pers,$_persvs)/$delta;			if ($req[$point]==5) $ydar *= 1.1;			if ($req[$point]==7) $ydar *= 1.2;			$ylov = ylov($_pers,$_persvs);			$sokr = sokr($_pers,$_persvs);			$yar  = yar ($_pers,$_persvs);			if ($_persvs["is_art"]<1) $_persvs["is_art"]=1;			if ($_pers["is_art"]<1) $_pers["is_art"]=1;			$yar  *= $_pers["is_art"];			$ylov *= $_persvs["is_art"];			$sokr *= $_pers["is_art"];			$ydar *= $_pers["is_art"];			$ydar = floor($ydar);			if ($ylov>70) $ylov = 70;			if ($sokr>70) $sokr = 70;			if (@$spd)			{				if ($spd["type"]==1)				{					 $_pers["udmin"] = $_pers["udmin"]/(1+$spd["value"]/100);					 $_pers["udmax"] = $_pers["udmax"]/(1+$spd["value"]/100);				}				if ($spd["type"]==2) $sokr = $sokr+$sokr*$spd["value"]/70;				if ($spd["type"]==3) $ylov = $ylov-$ylov*$spd["value"]/70;			}			if ($yar>rand(0,100))			{				$ydar *= 1.7;				$ydar = round($ydar);				if ($block=='') $block=',';				$block.='<font color=green>нанося яростный удар</font>,';			}			$ksokr = 2;			$CRITISISED = 0;			if (rand(0,100)<$sokr)			{				$ydar=round($ydar*$ksokr);				$CRITISISED = 1;			}			if ($_persvs[$bpoint]==1)			{				if ($ydar/(mtrunc($_persvs["kb"])/3+1)>2)				{$ydar*=0.3;				$block=", пробивая простой блок ,";}				else				{				$ydar=0;				$blocked = 1;				}			}			if ($_persvs[$bpoint]==2)			{				if ($ydar/(mtrunc($_persvs["kb"])/3+1)>3)				{$ydar*=0.2;				$block=", пробивая усиленный блок ,";}				else				{				$ydar=0;				$blocked = 1;				}			}			if ($_persvs[$bpoint]==5)			{				if ($ydar/(mtrunc($_persvs["kb"])/3+1)>5)				{					$ydar*=0.1;					$block=", пробивая крепчайший блок ,";				}				else				{					$ydar=0;					$blocked = 1;				}			}			unset($zid);			$z=1;						## Магия			if ($req[$point]=='magic') $zid = $req[$point."p"];			if ( $zid ) include (ROOT.'/inc/inc/magic.php');			###						$ydar = floor($ydar);			if ($blocked and $z==1)			{				$z=0;				$s=$nvs." <b>заблокировал".$malevs."</b> <font class=timef>«".$ud_name."»</font>";			}			if ($z==1 and rand(0,100)<$promax)			{				$z=0;				$s=$nyou." промах";				$ydar = 0;			}			if ($z==1 and rand(0,100)<$ylov)			{				$z=0;				$s= bit_icon("d",16).$nyou." ".$pitalsa." поразить соперника, но ".$nvs." <b>".$yvvs."</b> от <font class=timef>«".$ud_name."»</font>";				$ydar = 0;			}			if ($z==1 and $CRITISISED)			{				$z=0;				$s= bit_icon("s",16).$nyou." ".$block." поразил".$male." ".$nvs." на	<font class=bnick color=#CC0000><b>-".$ydar."</b></font> <font class=timef>«cокрушительный ".$ud_name."»</font>";			}			if ($z==1)			{				$z=0;				$s= bit_icon("t",16).$nyou." ".$block." поразил".$male." ".$nvs." на <b class=user>-".$ydar."</b> <font class=timef>«".$ud_name."»</font>";			}			if (@$spd and $spd["type"]==4 and !$blocked)			{				$_persvs["cma"]-=$spd["value"];				$_persvs["cma"]=mtrunc($_persvs["cma"]);				$s .= "(<font class=ma>-".$spd["value"]." МАНЫ</font>)";			}			if ($z==0)			{				$_persvs["chp"] -= $ydar;				$_pers["fexp"] += $ydar;				if (!$invvs)					$s .= "<font class=hp_in_f>[".mtrunc($_persvs["chp"])."/".$_persvs["hp"]."]</font>";			}						if ($MAGIC_LOG) $s = $MAGIC_LOG;						if ($_persvs["chp"]<=0 and $z<>2)			{				$_pers["fexp"]+= $_persvs["chp"];				$ydar += $_persvs["chp"];				$_persvs["chp"]=0;				if (($_persvs["uid"] or $_persvs["bid"]<0 or ($_persvs["level"]>($_pers["level"]+1) and $_persvs["rank_i"]>($_pers["rank_i"]-20*$_pers["is_art"]) and rand(0,100)<10)) and $_persvs["level"]>($_pers["level"]-2) and $fight["travm"]>=10)				{					$die=$nvs." <b>".$pogib."</b> , ".$nyou." опыт <font class=green>+".($_pers["level"]*10)."</font>.%".$die;					$_pers["kills"]++;				}				else $die=$nvs." <b>".$pogib."</b>.%".$die;				$str = '';				if (!$_persvs["uid"])include (ROOT.'/inc/inc/bots/drop.php');				else include (ROOT.'/inc/inc/fights/travm.php');				$die.=$str;			}			if ($z<>2)			{				if(!$_persvs["id_skin"])$_pers["exp_in_f"]+= experience($ydar,$_pers["level"],$_persvs["level"],$_persvs["uid"],$_persvs["rank_i"]);				else $_pers["exp_in_f"]+= experience($ydar*0.3,$_pers["level"],$_persvs["level"],$_persvs["uid"],$_persvs["rank_i"]);				$_pers["damage_give"]=$ydar;			}			if ($_pers["chp"]<=0)$_pers["chp"]=0;			if (strpos($_pers["aura"],'vampire')>0 and round($ydar/10)>0 and $no_mana==false and $_pers["chp"]>0 and $z<>2)			{				if (DAY_TIME==0)				{					$_pers["chp"]+=round($ydar/9);					$s.=".Вампиризм <font class=hp>+".round($ydar/9)."HP</font>";				}				else				{					$_pers["chp"]+=round($ydar/10);					$s.=".Вампиризм <font class=hp>+".round($ydar/10)."HP</font>";				}			}						$fall=$fall.$s;			if ($z<>2)			{				if ( $_persvs["uid"] > 0 )				{					if (!$en) $db->sql("UPDATE `users` SET `chp`='".$_persvs["chp"]."' ,`cma`='".$_persvs["cma"]."' ,`refr`=1 WHERE `uid`='".$_persvs["uid"]."'", __FILE__,__LINE__,__FUNCTION__,__CLASS__);					else $db->sql("UPDATE `users` SET `chp`='".$_persvs["chp"]."' ,`cma`='".$_persvs["cma"]."' WHERE `uid`='".$_persvs["uid"]."'", __FILE__,__LINE__,__FUNCTION__,__CLASS__);				}				else  $db->sql("UPDATE `bots_battle` SET `chp`='".$_persvs["chp"]."' ,`cma`='".$_persvs["cma"]."' WHERE `id`= ".$_persvs["id"]."", __FILE__,__LINE__,__FUNCTION__,__CLASS__);			}			$db->sql("UPDATE `users` SET `fexp`='".$_pers["fexp"]."', `chp`='".$_pers["chp"]."', `exp_in_f` = '".$_pers["exp_in_f"]."', `damage_give` = ".$_pers["damage_give"].", kills = ".$_pers["kills"]." WHERE `uid`='".$_pers["uid"]."'", __FILE__,__LINE__,__FUNCTION__,__CLASS__);		}		else $fall = $nyou." сделал".$malevs." контрольный удар по трупу";	}	if ($fall) $fall = $fall.". &nbsp;";	GLOBAL $player,$persvs;	$player->pers = catch_user($player->pers["uid"]);	if ($persvs["chp"]>0)	{		if ($persvs["uid"]) $persvs = catch_user($persvs["uid"]);		else $persvs = $db->sqla("SELECT * FROM bots_battle WHERE id= ".$persvs["id"]."", __FILE__,__LINE__,__FUNCTION__,__CLASS__);	}	else	{		$persvs = $db->sqla("SELECT * FROM users WHERE cfight=".$player->pers["cfight"]." and fteam<>".$player->pers["fteam"]." and chp>0", __FILE__,__LINE__,__FUNCTION__,__CLASS__);		if (!$persvs["uid"]) $persvs = $db->sqla("SELECT * FROM bots_battle WHERE cfight=".$player->pers["cfight"]." and fteam<>".$player->pers["fteam"]." and chp>0", __FILE__,__LINE__,__FUNCTION__,__CLASS__);	}	return $fall;}function experience($damage,$yourlvl,$vslvl,$notnpc,$rank){			if ($notnpc)				$koeff = 1.9;			else				$koeff = 0.6*sqrt(sqrt(($rank+1)/3));			if ($yourlvl<=2)				$koeff += 1.7;			if ($yourlvl<5) $koef += 0.7;			if ($notnpc or $yourlvl<4) $koeff *= sqrt(sqrt($vslvl+1.1));			if ($notnpc)			{			if ($yourlvl>=($vslvl+3)) $koeff *= 0.2*(($vslvl+1)/($yourlvl+1));			if ($yourlvl==($vslvl+2)) $koeff *= 0.5;			if ($yourlvl==($vslvl+1)) $koeff *= 0.7;			if ($yourlvl==($vslvl))   $koeff *= 1;			if ($yourlvl==($vslvl-1)) $koeff *= 1.4;			if ($yourlvl==($vslvl-2)) $koeff *= 1.8;			if ($yourlvl==($vslvl-3)) $koeff *= 2.6;			if ($yourlvl<($vslvl-3))  $koeff *= 3.0*(($vslvl+1)/($yourlvl+5));			}else			{			if ($yourlvl>=($vslvl+3)) $koeff *= 0.2*(($vslvl+1)/($yourlvl+1));			if ($yourlvl==($vslvl+2)) $koeff *= 0.5;			if ($yourlvl==($vslvl+1)) $koeff *= 0.7;			if ($yourlvl==($vslvl))   $koeff *= 1;			if ($yourlvl==($vslvl-1)) $koeff *= 1.2;			if ($yourlvl==($vslvl-2)) $koeff *= 1.4;			if ($yourlvl==($vslvl-3)) $koeff *= 1.6;			if ($yourlvl<($vslvl-3))  $koeff *= 2.0*(($vslvl+1)/($yourlvl+5));			}			$koeff *= mtrunc(0.9+($vslvl-$yourlvl)*0.10)+0.1;			return floor($damage*$koeff);}function ylov($_pers,$_persvs){	$vsR = mtrunc($_persvs["s2"]*($_persvs["mf2"]/100+1));	$yoR = mtrunc($_pers["s2"]*($_pers["mf3"]/100+1));	$ylov = 50*mtrunc(1-$yoR/$vsR)*sqrt($vsR/4);	$ylov *= mtrunc($_persvs["level"]-$_pers["level"])*0.20+1;	if ($ylov>70)	 $ylov=70;	if ($ylov<1)	 $ylov=0;	return $ylov;}function sokr($_pers,$_persvs){	$vsR = mtrunc($_persvs["s3"]*($_persvs["mf4"]/100+1));	$yoR = mtrunc($_pers["s3"]*($_pers["mf1"]/100+1));	$ylov = 50*mtrunc(1-$vsR/$yoR)*sqrt($yoR/4);	$ylov *= mtrunc($_pers["level"]-$_persvs["level"])*0.20+1;	if ($ylov>70)	 $ylov=70;	if ($ylov<1)	 $ylov=0;	return $ylov;}function yar($_pers,$_persvs){	$yar=(3+$_pers["mf5"]/5-$_pers["mf4"]/20)/5;	$yar *= mtrunc($_pers["level"]-$_persvs["level"])*0.20+1;	if($yar<2)	 $yar=2;	if($yar>90)	 $yar=90;	return $yar;}function ydar($_pers,$_persvs){	$ydar = rand($_pers["udmin"]*10,$_pers["udmax"]*10+10)/20;	$ydar = $ydar*sqrt($ydar);	$ydar *= mtrunc($_pers["level"]-$_persvs["level"])*0.20+1;	$kb = mtrunc($_persvs["kb"]+$_persvs["sb11"]);	$ydar = mtrunc($_pers["sb2"]+$_pers["s1"]+$ydar);	if ($kb<1) $kb = 1;	$ydar = $ydar*(pow(0.89,sqrt($kb))+0.1);	$ydar = mtrunc(rand($ydar-3,$ydar+3));	return floor($ydar);}// Функция удараfunction newbot_udar($point,$_botU){	GLOBAL $persvs,$player,$colors,$fight,$kl,$die,$PVS_NICK,$USER_NICK,$pitalsa,$yvvs,$male,$malevs,$pogib,$db;	if ($_botU[$point]==0 or !$player->pers or !$persvs) return;	//var_dump($persvs);	if ($persvs["invisible"]>tme()){$persvs["user"] = '<i>невидимка</i>';$invvs=1;$persvs["pol"]='female';} else $invvs=0;	$_SHIT_PLUS = 0;	if ($persvs["uid"] and $persvs["sb4"])		$_SHIT_PLUS += $db->sqlr("SELECT SUM(kb) FROM wp WHERE uidp=".intval($_persvs["uid"])." and weared=1 and stype='shit'",0, __FILE__,__LINE__,__FUNCTION__,__CLASS__)*$persvs["sb4"]/33;	$persvs["kb"] += $_SHIT_PLUS;		if (!$invvs) $nvs = "<font class=bnick color=".$colors[$persvs["fteam"]].">".$persvs["user"]."</font>[".$persvs["level"]."]";	else $nvs = "<font class=bnick color=".$colors[$persvs["fteam"]]."><i>невидимка</i></font>[??]";	$nyou = "<font class=bnick color=".$colors[$player->pers["fteam"]].">".$player->pers["user"]."</font>[".$player->pers["level"]."]";	if ($player->pers["pol"]=='female') $male='а'; else $male='';	if ($male=='а') $pitalsa = 'пыталась';	else $pitalsa = 'пытался';	if ($persvs["pol"]=='female')	{		$pogib = 'погибла';		$malevs='а';		$yvvs = 'увернулась';	}	else	{		$pogib = 'погиб';		$malevs='';		$yvvs = 'увернулся';	}	switch ($point)	{		case ("ug"): {$bpoint="bg";$ypoint="удар в голову";break;}		case ("ut"): {$bpoint="bt";$ypoint="удар в грудь";break;}		case ("uj"): {$bpoint="bj";$ypoint="удар по животу";break;}		case ("un"): {$bpoint="bn";$ypoint="удар по ногам";break;}	}	if ($_botU[$point]==1) $ud_name = 'простой ';	if ($_botU[$point]==2) $ud_name = 'прицельный ';	if ($_botU[$point]==5) $ud_name = 'оглушающий ';	$ud_name .= $ypoint;	$ud_name = $ud_name;	$fall = '';	//var_dump($_botU);	if (isset ($_botU[$point]) and $persvs["chp"]>0)	{		$kl=1;		$block='';		$blocked=0;		$ydar = ydar($player->pers,$persvs);		if ($_botU[$point]==2) $ydar *= 1.1;		if ($_botU[$point]==5) $ydar *= 1.2;		if ($persvs[$bpoint]==1)		{			if ($ydar/(mtrunc($persvs["kb"])+1)>2)			{				$ydar*=0.3;				$block=", пробивая простой блок ,";			}			else			{				$ydar=0;				$blocked = 1;			}		}		if ($persvs[$bpoint]==2)		{			if ($ydar/(mtrunc($persvs["kb"])+1)>3)			{				$ydar*=0.2;				$block=", пробивая усиленный блок ,";}			else			{				$ydar=0;				$blocked = 1;			}		}		if ($persvs[$bpoint]==5)		{			if ($ydar/(mtrunc($persvs["kb"])+1)>5)			{				$ydar*=0.1;				$block=", пробивая крепчайший блок ,";			}			else			{				$ydar=0;				$blocked = 1;			}		}		$ydar = floor($ydar);		$ylov = ylov($player->pers,$persvs);		$sokr = sokr($player->pers,$persvs);		$yar  = yar ($player->pers,$persvs);		if ($persvs["is_art"]<1) $persvs["is_art"]=1;		if ($player->pers["is_art"]<1) $player->pers["is_art"]=1;		$ylov *= $persvs["is_art"];		if ($ylov>70) $ylov = 70;		if ($sokr>70) $sokr = 70;		if ($yar>rand(0,100))		{			$ydar *= 1.4;			if ($block=='') $block=',';			$block.='<font color=green>нанося яростный удар</font>,';		}		$ydar = floor($ydar);		$ksokr = 2;		$z=1;		if ($blocked and $z==1)		{			$z=0;			$s=$nvs." <b>заблокировал".$malevs."</b> <font class=timef>«".$ud_name."»</font>";		}		if ($z==1 and rand(0,100)<$promax)		{			$z=0;			$s=$nyou." промах";		}		if ($z==1 and rand(0,100)<$ylov)		{			$z=0;			$s= bit_icon("d",16).$nyou." ".$pitalsa." поразить соперника, но ".$nvs." <b>".$yvvs."</b> от <font class=timef>«".$ud_name."»</font>";		}		if ($z==1 and rand(0,100)<$sokr)		{			$z=0;			$ydar=round($ydar*$ksokr);			$persvs["chp"]-=$ydar;			$player->pers["fexp"]+=$ydar;			if (!$invvs)$hpvs = "<font class=hp_in_f>[".mtrunc($persvs["chp"])."/".$persvs["hp"]."]</font>"; else $hpvs='';			$s= bit_icon("s",16).$nyou." ".$block." поразил".$male." ".$nvs." на	<font class=bnick color=#CC0000><b>-".$ydar."</b></font> <font class=timef>«cокрушительный ".$ud_name."»</font>".$hpvs;		}		if ($z==1)		{			$z=0;			$persvs["chp"]-=$ydar;			if (!$invvs)$hpvs = "<font class=hp_in_f>[".mtrunc($persvs["chp"])."/".$persvs["hp"]."]</font>"; else $hpvs='';			$s= bit_icon("t",16).$nyou." ".$block." поразил".$male." ".$nvs." на <b class=user>-".$ydar."</b> <font class=timef>«".$ud_name."»</font>".$hpvs;		} 		$player->pers["exp_in_f"]+= experience($ydar,$player->pers["level"],$persvs["level"],$persvs["uid"],$persvs["rank_i"]);		if ($persvs["chp"]<=0 and $z<>2)		{			$persvs["chp"]=0;			$die=$nvs." <b>".$pogib."</b>.%".$die;			if($persvs["uid"]) include ('inc/inc/fights/travm.php');			$die.=$str;		}		$fall=$fall.$s;		if($persvs["uid"]) $db->sql("UPDATE `users` SET `chp`='".$persvs["chp"]."' WHERE `uid`='".$persvs["uid"]."'", __FILE__,__LINE__,__FUNCTION__,__CLASS__);		else $db->sql("UPDATE `bots_battle` SET `chp`='".$persvs["chp"]."' WHERE `id`='".$persvs["id"]."'", __FILE__,__LINE__,__FUNCTION__,__CLASS__);		$db->sql("UPDATE `bots_battle` SET `exp_in_f`='".$player->pers["exp_in_f"]."' WHERE `id`='".$player->pers["id"]."'", __FILE__,__LINE__,__FUNCTION__,__CLASS__);	}	elseif($persvs["chp"]<=0) $fall = $nyou." сделал контрольный удар по трупу";	if ($fall) $fall = $fall.". &nbsp;";	$persvs["kb"] -= $_SHIT_PLUS;	return $fall;}function bit_icon($type,$size=0){	if ($size==0) $size = 60;	if ($type=='s') return "<img src=images/arena/bits/s/a".rand(1,13).".gif height=".$size." title=Сокрушительный>";	elseif ($type=='d') return "<img src=images/arena/bits/d/a".rand(1,7).".gif height=".$size." title=Уворот>";	else return "<img src=images/arena/bits/t/a".rand(1,11).".gif height=".$size." title=Точный>";}//by burezovfunction insert_drop($id,$uid,$durability = -1,$weared = 0 ,$user = ''){	GLOBAL $db;	$uid = intval($uid);	$id = intval($id);	if(is_scalar($id)) $v = $db->sqla("SELECT * FROM wp WHERE id='".$id."'", __FILE__,__LINE__,__FUNCTION__,__CLASS__);	else $v = $id;	$id = $v["id"];	if ($durability==-1)$durability=$v["max_durability"];	if (empty($v["id"])) return 0;	$user = $db->sqlr("SELECT user FROM users WHERE uid=".$uid,0, __FILE__,__LINE__,__FUNCTION__,__CLASS__);	$_colls = '';	$_params = '';	$r = all_params();	foreach ($r as $param)	{		if($v[$param]!=0)		{			$_colls .= ',`'.$param.'`';			$_params .= ",'".$v[$param]."'";		}		$param = 't'.$param;		if($v[$param]!=0)		{			$_colls .= ',`'.$param.'`';			$_params .= ",'".$v[$param]."'";		}	}	$db->sql("INSERT INTO `wp` ( `id` , `uidp` , `weared` ,`id_in_w`, `price` , `dprice` , `image` , `index` , `type` , `stype` , `name` , `describe` , `weight` , `where_buy` , `max_durability` , `durability` , `present` , `clan_sign` , `clan_name` ,`radius` , `slots` ,`arrows` ,`arrows_max` ,`arrow_name` , `arrow_price` , `tlevel` ,`p_type` , `user`, `material_show`, `material` ".$_colls.")		VALUES (0, '".$uid."', '".$weared."','".$id."','".$v["price"]."', '".$v["dprice"]."', '".$v["image"]."', '".$v["index"]."', '".$v["type"]."', '".$v["stype"]."', '".$v["name"]."', '".$v["describe"]."', '".$v["weight"]."', '".$v["where_buy"]."', '".$v["max_durability"]."', '".$durability."', '".$v["present"]."', '', '', '".$v["radius"]."', '".$v["slots"]."', '".$v["arrows"]."', '".$v["arrows_max"]."', '".$v["arrow_name"]."', '".$v["arrow_price"]."', '".$v["tlevel"]."','".$v["p_type"]."', '".$user."', '".$v["material_show"]."', '".$v["material"]."' ".$_params.");", __FILE__,__LINE__,__FUNCTION__,__CLASS__);	return $db->insert_id();}?>